if (Test-Path (Join-Path $claude "CLAUDE.md"))      { Ok ".claude\CLAUDE.md" }           else { Bad ".claude\CLAUDE.md немає" }
if (Test-Path (Join-Path $claude "settings.json"))  { Ok ".claude\settings.json" }       else { Bad ".claude\settings.json немає" }
